More formally, a wavelet family $\Psi_{j,k}$ is a set of functions generated by dilations and translations of a unique mother wavelet $\Psi$:
\begin{equation}
\label{def:wave_funcs}
 \Psi_{j,k}(t) = a^{\frac{j}{2}} \Psi(a^j t - k),
\end{equation}

where $j,k \in \mathbb{Z}$ and $a>0$.

\begin{equation}
\label{def:wave_funcs}
 \Psi_{j,k}(t) = a^{\frac{j}{2}} \Psi(a^j t - k),
\end{equation}

\begin{equation}
f(t) = \sum_{k \in \mathbb{Z}} c_{k}\phi_{0,k}(t) + \sum_{j,k \in \mathbb{Z}} \mathbf{v}_{j,k}\Psi_{j,k}(t)
\label{eq:wavelet_basis},
\end{equation}

This property is typically used for signal denoising
using a three-step procedure \cite{donoho1995noising}: \\
\begin{equation}
\hat{\mathbf{x}} \equiv \mathbf{W}^{-1} \eta_{\lambda} (\mathbf{W} \mathbf{x})
\label{eq:DWT_denoising}
\end{equation}

where $\eta_{\lambda}$ is a nonlinear shrinkage (smoothing) operator, for example entry-wise soft-threshold operator with parameter
$\lambda$: $\eta_{\lambda}(\mathbf{v}) = \text{sgn}(\mathbf{v})(|\mathbf{v}| - \lambda)_{+}$.

\begin{equation}
\hat{\mathbf{x}} \equiv \mathbf{W}^{-1} \eta_{\lambda} (\mathbf{W} \mathbf{x})
\label{eq:DWT_denoising}
\end{equation}

In standard K-means clustering, the goal is to
maximize the \textit{Between Cluster Sum of Squares} (BCSS), which can be represented as a sum
$1^T \mathcal{D}$ where $\mathcal{D}$ is a vector representing the contribution of the wavelet coefficient $j$ to the BCSS, with

\begin{equation}
	\mathcal{D}_j \equiv \frac{1}{n} \sum_{i_{1},i_2=1}^{n} {d_{i_{1},i_{2},j } } - \sum_{k=1}^{K} { \frac{1}{n_{k}} \sum_{i_{1},i_{2} \in C_{k} }{ d_{i_{1},i_{2},j }}}.
\label{eq:BCSS}
\end{equation}

\begin{equation}
	\mathcal{D}_j \equiv \frac{1}{n} \sum_{i_{1},i_2=1}^{n} {d_{i_{1},i_{2},j } } - \sum_{k=1}^{K} { \frac{1}{n_{k}} \sum_{i_{1},i_{2} \in C_{k} }{ d_{i_{1},i_{2},j }}}.
\label{eq:BCSS}
\end{equation}

We get the following sparse K-means \cite{witten2010framework} constrained optimization problem, where sparsity is promoted in the wavelet domain:
\begin{equation}
	\begin{aligned}
		& \underset{C_{1},C_{2},...C_{k},\mathbf{w}}{\text{argmax}} \mathbf{w}^T\mathcal{D} \\
		& s.t. \quad \mathbf{w} \in \mathcal{B}_2(0, 1) \cap \mathcal{B}_1(0, s) \cap \mathbb{R}^T_{+} \\
	\end{aligned}
\label{eq:sparse_k_means_wavelet_ver2}
\end{equation}

where $\mathcal{B}_p(0, r) \in \mathbb{R}^T$ is the $L_p$ ball centered at zero with radius $r$, and $\mathbb{R}^T_{+}$ is the positive orthant,
$\mathbb{R}^T_{+} \equiv \{ \mathbf{w} \in \mathbb{R}^T, w_j \geq 0, \forall j=1,..,T \}$.

\begin{equation}
	\begin{aligned}
		& \underset{C_{1},C_{2},...C_{k},\mathbf{w}}{\text{argmax}} \mathbf{w}^T\mathcal{D} \\
		& s.t. \quad \mathbf{w} \in \mathcal{B}_2(0, 1) \cap \mathcal{B}_1(0, s) \cap \mathbb{R}^T_{+} \\
	\end{aligned}
\label{eq:sparse_k_means_wavelet_ver2}
\end{equation}

Define the group-norm with respect to the partition $\mathcal{G}$ \cite{bach2011convex},

\begin{equation}
|| \mathbf{v} ||_{\mathcal{G}} \equiv \sum_{g \in \mathcal{G}} \sqrt{|g|} || \mathbf{v}_{(g)} ||_2
\label{def:group_norm}
\end{equation}
where we multiply the vector norms $|| \mathbf{v}_{(g)} ||_2$ by $\sqrt{|g|}$ as in \cite{chen2012compressive} and \cite{friedman2010note},
to give greater penalties to larger groups (other coefficients may also be used).

\begin{equation}
|| \mathbf{v} ||_{\mathcal{G}} \equiv \sum_{g \in \mathcal{G}} \sqrt{|g|} || \mathbf{v}_{(g)} ||_2
\label{def:group_norm}
\end{equation}

\begin{equation}
\begin{aligned}
& \underset{C_{1},C_{2},...C_{K},\mathbf{w}}{\text{argmax}} \mathbf{w}^T\mathcal{D} \\
& s.t. \quad \mathbf{w} \in \mathcal{B}_2(0, 1) \cap {\mathcal{B}_{(\mathcal{G})}}(0, s) \cap \mathbb{R}^T_{+}
\end{aligned}
\label{problem_group_sparse}
\end{equation}

	{\bf Input:} $\mathbf{v}^{(1)},\mathbf{v}^{(2)},...,\mathbf{v}^{(n)}$, $K$, $iters$, $\mathcal{G}$, $s$ \\
	{\bf Output:} Clusters $C_1,C_2,...,C_K$
	\begin{enumerate}
		\item
		\textbf{Initialize}: Set $w_1=w_2=...=w_T=\frac{1}{\sqrt{T}}$
		\item
		\textbf{for} i=$1:iters$
		\begin{enumerate}
			\item
			Apply K-means on $\sqrt{\mathbf{w}} \odot \mathbf{v}^{(1)},..., \sqrt{\mathbf{w}} \odot \mathbf{v}^{(n)}$
			\item
			Hold $C_1,...,C_K$ fixed, solve (\ref{problem_group_sparse}) w.r.t $\mathbf{w}$, with tuning parameter $s$ and partition $\mathcal{G}$
		\end{enumerate}
		\item
		\textbf{Return} $C_1,...,C_K$

	\end{enumerate}
	\protect\caption{Group-Sparse K-means}
\label{alg:group_sparse_kmeans}

let Coefficients using Group Sparsity}

In our time-series clustering context, each scale $g$ of the wavelets coefficients can be thought of as a group,
together forming a multi-scale view of the signal.

For a function $f(t)$ the $0$-th scattering layer is obtained by a convolution,
\begin{equation}
S^{(0)} \equiv f \star \phi
\label{eq:scat_layer1}
\end{equation}

where $f \star g(t) \equiv \int_{s=-\infty}^{\infty} f(s) g(t-s) ds$ and
$\phi$ is an averaging filter.

\begin{equation}
S^{(0)} \equiv f \star \phi
\label{eq:scat_layer1}
\end{equation}

\begin{equation}
S_{j_1}^{(1)} \equiv |f \star \Psi^{(1)}_{j_1}| \star \phi, \quad \forall j_1 \in J_1
\label{eq:scat_layer2}
\end{equation}

This process above continues in the same way, with the scattering functions at the $l$-th layer given by
\begin{equation}
S^{(l)}_{j_1,..,j_{l}} \equiv | .. ||f \star \Psi^{(1)}_{j_1}| \star \Psi^{(2)}_{j_2}| \star \Psi^{(3)}_{j_3}| \star,...,\star \Psi^{(l)}_{j_l}| \star \phi,
\: \forall (j_1,..,j_l) \in J_1 \times J_2 \times .. \times J_l.
\label{eq:scat_layerk}
\end{equation}

\begin{equation}
S^{(l)}_{j_1,..,j_{l}} \equiv | .. ||f \star \Psi^{(1)}_{j_1}| \star \Psi^{(2)}_{j_2}| \star \Psi^{(3)}_{j_3}| \star,...,\star \Psi^{(l)}_{j_l}| \star \phi,
\: \forall (j_1,..,j_l) \in J_1 \times J_2 \times .. \times J_l.
\label{eq:scat_layerk}
\end{equation}

\begin{equation}
\mathcal{G} = \big\{ g_{j_1,...,j_l}, \forall l=0,..,L, \forall (j_1,...,j_l) \in J_1 \times .. \times J_l \big\}
\end{equation}

\begin{equation}
g_{j_1,j_2,...,j_l}= \Big\{v_{j_1,\ldots,j_l}^{(l)}(\frac{k\Delta_t}{2}): k = 0,\ldots, \lceil\frac{2T}{\Delta_t}\rceil \Big\}
\end{equation}

